import{_ as u,a0 as l,w as a,s as r,I as e,x as s,a1 as n,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何创建 Ubuntu 持久化立付 U 盘 | LCTT x X-CMD","titleTemplate":false,"description":"如何创建 Ubuntu 持久化立付 U 盘 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何创建 Ubuntu 持久化立付 U 盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何创建 Ubuntu 持久化立付 U 盘 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230905 How to Create Persistent Live USB of Ubuntu","title":"如何创建 Ubuntu 持久化立付 U 盘","tag":"202309","desc":""},"relativePath":"202309/20230905 How to Create Persistent Live USB of Ubuntu.md","filePath":"[post].md"}'),d={name:"202309/20230905 How to Create Persistent Live USB of Ubuntu.md"};function b(m,t,g,f,U,h){const i=l("Link");return a(),r("div",null,[t[27]||(t[27]=e("h1",{id:"如何创建-ubuntu-持久化立付-u-盘",tabindex:"-1"},[s("如何创建 Ubuntu 持久化立付 U 盘 "),e("a",{class:"header-anchor",href:"#如何创建-ubuntu-持久化立付-u-盘","aria-label":"Permalink to “如何创建 Ubuntu 持久化立付 U 盘”"},"​")],-1)),t[28]||(t[28]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202309/06/162606ivjl1zoohb1h8vuo.jpg",alt:""})],-1)),t[29]||(t[29]=e("blockquote",null,[e("p",null,"体验带有持久化的立付 U 盘，你在立付会话中做出的所有改动都会被保存。在此教程中，你将学习如何创建一个持久化的 U 盘。")],-1)),t[30]||(t[30]=e("p",null,"如果我告诉你，你能将完整的 Ubuntu 系统装载在一个可移动的 U 盘上，你会有何感想？",-1)),e("p",null,[t[1]||(t[1]=s("在外置 U 盘上 ",-1)),n(i,{href:"https://itsfoss.com/intsall-ubuntu-on-usb/"},{default:o(()=>[...t[0]||(t[0]=[s("安装 Ubuntu",-1)])]),_:1}),t[2]||(t[2]=s(" 过程相当复杂。一种更容易的方法是制作一个带有持久化存储的 ",-1)),t[3]||(t[3]=e("ruby",null,[s("立付"),e("rt",null,"Live")],-1)),t[4]||(t[4]=s(" U 盘，这样你对 U 盘做出的改动都会被保存下来。",-1))]),e("p",null,[t[6]||(t[6]=s("请相信我，这个过程跟使用 ",-1)),n(i,{href:"https://itsfoss.com/install-etcher-linux/"},{default:o(()=>[...t[5]||(t[5]=[s("BalenaEtcher",-1)])]),_:1}),t[7]||(t[7]=s(" 或其他任何刻录工具创建可引导驱动器的过程十分相似。",-1))]),t[31]||(t[31]=p('<p>然而，我们在开始之前，让我们先弄清楚持久化立付 U 盘是什么。</p><h3 id="什么是持久化立付-u-盘" tabindex="-1">什么是持久化立付 U 盘？ <a class="header-anchor" href="#什么是持久化立付-u-盘" aria-label="Permalink to “什么是持久化立付 U 盘？”">​</a></h3><p>当你使用立付 Linux U 盘时，你在 <ruby>立付会话<rt>Live session</rt></ruby> 中做出的所有更改，在重启以后都将丢失。比如，你必须重新连接 Wi-Fi，并且你下载的文件及安装的应用均不会被保留。而持久化立付 U 盘将会为你保存这些所有的更改。</p><p>这样，你就可以将该 U 盘作为一个外置操作系统使用，它将会保存你所做出的所有更改，比如创建用户账号，安装软件包，和一切你通常在电脑上做的事情。</p><p>当然，保存的文件数量将取决于你使用的 U 盘的大小！</p><p>但你已经明白我要表达的意思了吧。那么，我们开始学习如何创建一个带有持久性的 Ubuntu 立付 U 盘吧。</p><h3 id="如何创建一个持久化的-ubuntu-u-盘" tabindex="-1">如何创建一个持久化的 Ubuntu U 盘 <a class="header-anchor" href="#如何创建一个持久化的-ubuntu-u-盘" aria-label="Permalink to “如何创建一个持久化的 Ubuntu U 盘”">​</a></h3><p>在这个教程中，我将引导你完成一个持久化的 Ubuntu U 盘的制作过程：</p><ul><li>通过在 Windows 上的 Rufus 工具</li><li>或者，通过在 Linux 上的 mkusb 工具</li></ul><p>你可以参照教程中的适合你的部分。</p><blockquote><p>📋 本教程中，你将会创建一个 Ubuntu 的持久化 U 盘。并非所有的 Linux 发行版都支持数据的持久化存储，所以这个方法可能并非所有的发行版本适用。</p></blockquote><h3 id="方法-1-在-windows-上创建持久化的-ubuntu-u-盘" tabindex="-1">方法 1：在 Windows 上创建持久化的 Ubuntu U 盘 <a class="header-anchor" href="#方法-1-在-windows-上创建持久化的-ubuntu-u-盘" aria-label="Permalink to “方法 1：在 Windows 上创建持久化的 Ubuntu U 盘”">​</a></h3><p>在 Windows 上创建一个持久化的 Ubuntu U 盘，我会使用 Rufus，这是一款自由开源工具，专门用于将 ISO 文件刻录到 U 盘上。</p>',13)),e("p",null,[t[9]||(t[9]=s("请访问 ",-1)),n(i,{href:"https://rufus.ie/en/"},{default:o(()=>[...t[8]||(t[8]=[s("Rufus 的官方下载页面",-1)])]),_:1}),t[10]||(t[10]=s("，获取 Windows 版本的可执行文件：",-1))]),t[32]||(t[32]=p('<p><img src="https://itsfoss.com/content/images/2023/09/Download-Rufus-to-create-persistant-Ubuntu-drive-in-Windows.png" alt=""></p><p>然后，打开 Rufus，它将要求以管理员身份运行；请授予该权限，因为你即将在外部驱动器上做改动，需要相应的权限。</p><p>接下来，根据以下步骤使用 Rufus 创建持久化 U 盘：</p><ul><li>选中 U 盘设备（如果只有一个 U 盘，它将默认被选中）。</li><li>点击 “<ruby>选择<rt>Select</rt></ruby>” 按钮，在文件管理器中选择 ISO 文件。</li><li>你可以使用滑块或直接设定持久化分区的大小（可以放心地设定为最大值）。</li><li>其他选项保持默认设置（除非你清楚在做什么）。</li><li>点击 “<ruby>开始<rt>Start</rt></ruby>” 按钮，开始进行刻录。</li></ul><p><img src="https://itsfoss.com/content/images/2023/09/Use-rufus-to-create-Ubuntu-persistant-drive.png" alt=""></p><p>该程序你会告诉你，选中的驱动器上的所有数据将会被删除，所以你可以放心忽略这个警告。</p><p>完成后，我们可以来瞧瞧如何在 Windows 中直接启动到 UEFI 设置。</p><h4 id="通过-u-盘启动-简化版" tabindex="-1">通过 U 盘启动（简化版） <a class="header-anchor" href="#通过-u-盘启动-简化版" aria-label="Permalink to “通过 U 盘启动（简化版）”">​</a></h4><p>这个方法应适用于大多数用户，如果无效，你总是可以选择传统的方式，那就是重新启动系统并按下 <code>Esc</code>、<code>Delete</code>、<code>F1</code>、<code>F2</code>、<code>F10</code>、<code>F11</code> 或 <code>F12</code> 等按键。</p><p>步骤如下：按 <code>Win + X</code>，然后以管理员身份启动 Windows PowerShell：</p><p><img src="https://itsfoss.com/content/images/2023/09/Start-Windows-powershell-as-admin.png" alt=""></p><p>一旦你看见提示符，直接运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shutdown.exe /r /fw</span></span></code></pre></div><p>这将会计划一个关机动作，稍后，你会进入到 UEFI 固件设置。</p><p>到了这步，选择 U 盘作为首选的启动选项并保存设置：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-UEFI-1.jpg" alt=""></p><p>你会看到一个正常的 GRUB 屏幕：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-persisted-storage-USB-drive-made-using-Rufus-on-Windows-machine.png" alt=""></p><p>当你启动后，选择试用 Ubuntu 的选项，然后你所做的任何改动都可以被保存下来，即使你重新启动了电脑也无所谓。</p><h3 id="方法-2-在-ubuntu-linux-上创建持久化-ubuntu-u-盘" tabindex="-1">方法 2：在 Ubuntu Linux 上创建持久化 Ubuntu U 盘 <a class="header-anchor" href="#方法-2-在-ubuntu-linux-上创建持久化-ubuntu-u-盘" aria-label="Permalink to “方法 2：在 Ubuntu Linux 上创建持久化 Ubuntu U 盘”">​</a></h3><blockquote><p>🚧 请注意，这种方法主要适用于 Ubuntu 和 Debian 的 ISO。</p></blockquote><p>如果你还不知道，<code>mkusb</code> 是一个带有 GUI 的工具，让你能够将 ISO 文件刷到磁盘驱动器上，并且有附加功能，例如在 Ubuntu 上创建持久化驱动器。</p><p>你需要添加 <code>mkusb</code> 的 PPA 来进行安装，具体命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mkusb/ppa</span></span></code></pre></div><p>要使改变生效，需要更新软件库索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>最后，安装 <code>mkusb</code> 以及其他相关软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install --install-recommends mkusb mkusb-nox usb-pack-efi</span></span></code></pre></div><p>就这样！</p><p>首先，从系统菜单启动 <code>mkusb</code> 工具，它会提示你输入超级用户密码：</p><p><img src="https://itsfoss.com/content/images/2023/08/Start-mkusb-tool-from-system-menu.png" alt=""></p><p>操作完成后，它会提示你所有驱动器上的数据将会被新数据覆盖。</p><p>只需简单地点击 “OK” 按钮即可：</p><p><img src="https://itsfoss.com/content/images/2023/08/Data-will-be-wiped-warning-.png" alt=""></p><p>然后它会显示 <code>mkusb</code> 工具能执行的多项操作，你需要选择第一选项 “<ruby>安装（制作一个启动设备）<rt>Install (make a boot device)</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-first-option-in-mkusb-tool-to-create-persistent-USB-drive-of-Ubuntu.png" alt=""></p><p>接下来，它会显示许多安装选项，你需要选择第三个选项 “<ruby>持久化立付（仅针对 Debian 和 Ubuntu）<rt>&#39;Persistent live&#39; - only Debian and Ubuntu</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-persistent-option.png" alt=""></p><p>在下一个步骤中，它会让你在多种方法/工具中选择一个，如果没有使用特定类型的版本，例如超精简版本，建议使用第一个名为 “dus-Iso2usb” 的方法：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-the-grub-option.png" alt=""></p><p>接着，它会让你从文件管理器中选择你需要的 ISO 文件：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-an-ISO-file-to-create-persistent-USB-from-Ubuntu.png" alt=""></p><p>工具会显示已选 ISO 文件的名称，以及创建持久化 U 盘所要使用的工具：</p><p><img src="https://itsfoss.com/content/images/2023/08/Showing-seelcted-ISO-file.png" alt=""></p><p>下一步，你需要选择驱动器将之前选择的 ISO 文件刷入：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-drive-to-create-persistent-drive.png" alt=""></p><p>以上全部完成后，将会有 3 个选项供你选择。如果你不确定使用哪一个，那么就点击 “<ruby>使用默认<rt>Use defaults</rt></ruby>” 按钮，但是大多数用户选择第二个选项 “grold” 即可（我也是选择这个）：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-bootloader.png" alt=""></p><p>检查一切都无误后，点击 “<ruby>开始<rt>Go</rt></ruby>” 开始刷新过程：</p><p><img src="https://itsfoss.com/content/images/2023/08/Select-go-ahead-option-in-mkusb-to-create-persistent-USB-drive.png" alt=""></p><p>现在，刷入过程已经开始了！</p><p><img src="https://itsfoss.com/content/images/2023/08/Flashing-process-to-make-persistent-usb-of-Ubuntu.png" alt=""></p><p><strong>注意，这个刷入过程会比你使用 BalenaEtcher 刷入要长一些时间！</strong></p><p>完成后，会有通知告诉你，过程已经完成，此时你可以取下 U 盘，然后重新插上，以查看更改的内容：</p><p><img src="https://itsfoss.com/content/images/2023/08/Persistent-drive-has-been-made.png" alt=""></p><h4 id="从持久化-u-盘启动" tabindex="-1">从持久化 U 盘启动 <a class="header-anchor" href="#从持久化-u-盘启动" aria-label="Permalink to “从持久化 U 盘启动”">​</a></h4><p>如果你要从 U 盘启动，通常可以重启你的系统，连续按下对应的按钮即可，但这已经是旧方法了！</p><p>在 Linux 中，有一种更为简便的方式访问 BIOS，你只需在终端执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot --firmware-setup</span></span></code></pre></div><p>然后，进入启动菜单并将 U 盘设置为首选的启动选项：</p><p><img src="https://itsfoss.com/content/images/2023/09/Boot-from-UEFI.jpg" alt=""></p><p>一旦你从 U 盘启动，你将有两个选项：</p><ul><li>带有持久化模式的 ISO</li><li>以实时模式进行启动</li></ul><p>如其名，你需要选择第一个选项以启动进入 Ubuntu 的持久化模式：</p><p><img src="https://itsfoss.com/content/images/2023/08/Boot-from-persisted-storage-USB-drive.png" alt=""></p>',65)),e("p",null,[t[12]||(t[12]=s("现在，你可以进行各种修改，如安装你喜欢的软件包，",-1)),n(i,{href:"https://learnubuntu.com/add-delete-users/"},{default:o(()=>[...t[11]||(t[11]=[s("创建新用户",-1)])]),_:1}),t[13]||(t[13]=s(" 等等！",-1))]),t[33]||(t[33]=e("p",null,"我希望这个指南对你有所帮助。",-1)),t[34]||(t[34]=e("p",null,[e("em",null,"（题图：MJ/423c72d6-d6eb-4146-acd5-1e58eed11f41）")],-1)),t[35]||(t[35]=e("hr",null,null,-1)),e("p",null,[t[15]||(t[15]=s("via: ",-1)),n(i,{href:"https://itsfoss.com/ubuntu-persistent-live-usb/"},{default:o(()=>[...t[14]||(t[14]=[s("https://itsfoss.com/ubuntu-persistent-live-usb/",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=s("作者：",-1)),n(i,{href:"https://itsfoss.com/author/sagar/"},{default:o(()=>[...t[16]||(t[16]=[s("Sagar Sharma",-1)])]),_:1}),t[20]||(t[20]=s(" 选题：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[17]||(t[17]=[s("lujun9972",-1)])]),_:1}),t[21]||(t[21]=s(" 译者：ChatGPT 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[18]||(t[18]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[24]||(t[24]=s("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[s("LCTT",-1)])]),_:1}),t[25]||(t[25]=s(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[s("Linux中国",-1)])]),_:1}),t[26]||(t[26]=s(" 荣誉推出",-1))])])}const x=u(d,[["render",b]]);export{S as __pageData,x as default};
